const src = $json.body ?? $json;

// Supports both a simplified portfolio payload and a Meta-style webhook payload.
let waId = src.wa_id;
let displayName = src.name ?? '';
let text = src.text;
let messageId = src.message_id;
let timestamp = src.timestamp;
let rawPayload = src;

if (!waId && src.entry?.[0]?.changes?.[0]?.value) {
  const value = src.entry[0].changes[0].value;
  const msg = value.messages?.[0];

  // Delivery/read status events do not contain a customer message.
  if (!msg) {
    return [{ json: { ignore: true, reason: 'non_message_event', raw_payload: src } }];
  }

  waId = msg.from;
  displayName = value.contacts?.[0]?.profile?.name ?? '';
  messageId = msg.id;
  timestamp = msg.timestamp ? new Date(Number(msg.timestamp) * 1000).toISOString() : new Date().toISOString();

  if (msg.type === 'text') text = msg.text?.body;
  else if (msg.type === 'button') text = msg.button?.text;
  else if (msg.type === 'interactive') {
    text = msg.interactive?.button_reply?.title ?? msg.interactive?.list_reply?.title ?? '';
  } else {
    text = '[unsupported message type: ' + String(msg.type ?? 'unknown') + ']';
  }
}

waId = String(waId ?? '').trim();
text = String(text ?? '').trim();

if (!waId || !text) {
  return [{ json: { ignore: true, reason: 'missing_wa_id_or_text', raw_payload: src } }];
}

return [{
  json: {
    ignore: false,
    wa_id: waId,
    display_name: String(displayName ?? ''),
    message_text: text,
    provider_message_id: String(messageId ?? ''),
    received_at: timestamp || new Date().toISOString(),
    raw_payload: rawPayload
  }
}];

const inbound = $('Normalize WhatsApp Message').first().json;
const raw = $json;
const lead = Array.isArray(raw) ? (raw[0] ?? {}) : (Array.isArray(raw.body) ? (raw.body[0] ?? {}) : raw);

return [{
  json: {
    ...inbound,
    current_lead: {
      wa_id: lead.wa_id ?? inbound.wa_id,
      display_name: lead.display_name ?? inbound.display_name,
      lead_stage: lead.lead_stage ?? 'NEW',
      product_interest: lead.product_interest ?? '',
      company: lead.company ?? '',
      role: lead.role ?? '',
      budget: lead.budget ?? '',
      timeline: lead.timeline ?? '',
      pain_point: lead.pain_point ?? '',
      objection: lead.objection ?? '',
      last_intent: lead.last_intent ?? '',
      lead_score: Number(lead.lead_score ?? 0),
      meeting_status: lead.meeting_status ?? 'not_requested',
      preferred_meeting_time: lead.preferred_meeting_time ?? '',
      human_handoff: Boolean(lead.human_handoff),
      opted_out: Boolean(lead.opted_out),
      final_outcome: lead.final_outcome ?? null,
      next_followup_at: lead.next_followup_at ?? null
    }
  }
}];

parameters.text:
=Interpret the latest WhatsApp sales message and extract structured signals.

Current lead state: {{ JSON.stringify($json.current_lead) }}
Latest customer message: {{ $json.message_text }}

Choose intent from: greeting, product_question, discovery_answer, qualification_answer, objection, booking_request, booking_confirmation, human_request, purchase_signal, decline, opt_out, other.

Extract only information actually present or strongly implied by the message. Keep unknown fields empty. Do not choose the sales stage.

parameters.jsCode:
const ctx = $('Build Persistent Sales Context').first().json;
const raw = $json.output && typeof $json.output === 'object' ? $json.output : $json;
const old = ctx.current_lead;

const pick = (fresh, previous) => {
  const v = String(fresh ?? '').trim();
  return v || String(previous ?? '');
};

const signals = {
  intent: String(raw.intent ?? 'other').toLowerCase(),
  product_interest: pick(raw.product_interest, old.product_interest),
  company: pick(raw.company, old.company),
  role: pick(raw.role, old.role),
  budget: pick(raw.budget, old.budget),
  timeline: pick(raw.timeline, old.timeline),
  pain_point: pick(raw.pain_point, old.pain_point),
  objection: pick(raw.objection, old.objection),
  preferred_meeting_time: pick(raw.preferred_meeting_time, old.preferred_meeting_time),
  wants_booking: Boolean(raw.wants_booking),
  booking_confirmed: Boolean(raw.booking_confirmed),
  wants_human: Boolean(raw.wants_human),
  purchase_signal: Boolean(raw.purchase_signal),
  opted_out: Boolean(raw.opted_out),
  confidence: Math.max(0, Math.min(1, Number(raw.confidence ?? 0) || 0))
};

let score = 0;
if (signals.pain_point) score += 20;
if (signals.product_interest) score += 15;
if (signals.company) score += 10;
if (signals.role) score += 10;
if (signals.budget) score += 15;
if (signals.timeline) score += 15;
if (signals.purchase_signal) score += 10;
if (signals.wants_booking || signals.booking_confirmed) score += 5;
score = Math.min(score, 100);

const current = String(old.lead_stage ?? 'NEW').toUpperCase();
const terminal = new Set(['WON','LOST','NURTURE']);
let next = current;
let reason = 'No stage transition required.';

if (terminal.has(current)) {
  next = current;
  reason = 'Terminal stage is human-controlled and remains unchanged.';
} else if (signals.opted_out || signals.intent === 'opt_out') {
  next = 'LOST';
  reason = 'Prospect explicitly opted out.';
} else if (signals.wants_human || signals.intent === 'human_request') {
  next = 'HUMAN_HANDOFF';
  reason = 'Prospect explicitly requested a person.';
} else if (signals.booking_confirmed && current === 'BOOKING') {
  next = 'HUMAN_HANDOFF';
  reason = 'Booking was confirmed; hand off to sales owner.';
} else if (signals.wants_booking || signals.intent === 'booking_request') {
  next = 'BOOKING';
  reason = 'Prospect requested a meeting or call.';
} else if (current === 'NEW') {
  next = 'DISCOVERY';
  reason = 'First usable prospect conversation started.';
} else if (current === 'DISCOVERY' && (signals.pain_point || signals.product_interest)) {
  next = 'QUALIFYING';
  reason = 'Pain point or product interest has been captured.';
} else if (current === 'QUALIFYING' && score >= 45 && signals.purchase_signal) {
  next = 'INTERESTED';
  reason = 'Qualification signals and explicit buying interest are present.';
}

let meetingStatus = old.meeting_status ?? 'not_requested';
if (next === 'BOOKING') meetingStatus = signals.booking_confirmed ? 'confirmed' : 'requested';
if (next === 'HUMAN_HANDOFF' && current === 'BOOKING' && signals.booking_confirmed) meetingStatus = 'confirmed';

const humanHandoff = next === 'HUMAN_HANDOFF' ? true : Boolean(old.human_handoff);
const optedOut = Boolean(old.opted_out) || signals.opted_out;
const finalOutcome = next === 'LOST' && signals.opted_out ? 'LOST' : (old.final_outcome ?? null);

let nextFollowupAt = null;
if (!humanHandoff && !optedOut && !terminal.has(next) && !['BOOKING'].includes(next)) {
  const hours = next === 'INTERESTED' ? 24 : 48;
  nextFollowupAt = new Date(Date.now() + hours * 3600 * 1000).toISOString();
}

return [{
  json: {
    ...ctx,
    signals,
    previous_stage: current,
    next_stage: next,
    stage_changed: next !== current,
    stage_reason: reason,
    lead_score: score,
    meeting_status: meetingStatus,
    human_handoff: humanHandoff,
    opted_out: optedOut,
    final_outcome: finalOutcome,
    next_followup_at: nextFollowupAt
  }
}];

const state = $('Apply Sales State Machine').first().json;
const output = String($json.text ?? $json.output ?? $json.response ?? '').trim();

return [{
  json: {
    ...state,
    reply_text: output || (state.human_handoff
      ? 'Thanks — I’ll have someone from the team take over from here.'
      : 'Thanks. I’ve noted that and we’ll take the next step from here.')
  }
}];

const s = $('Normalize Reply').first().json;
return [{
  json: {
    ...s,
    should_schedule_followup: Boolean(s.next_followup_at) && !s.human_handoff && !s.opted_out,
    should_handoff: Boolean(s.human_handoff)
  }
}];
